// RunPropertyAssignmentTestForConnection_Properties_Spec tests if a specific instance of Connection_Properties_Spec can be assigned to storage and back losslessly
func RunPropertyAssignmentTestForConnection_Properties_Spec(subject Connection_Properties_Spec) string {
	// Copy subject to make sure assignment doesn't modify it
	copied := subject.DeepCopy()

	// Use AssignPropertiesTo() for the first stage of conversion
	var other storage.Connection_Properties_Spec
	err := copied.AssignProperties_To_Connection_Properties_Spec(&other)
	if err != nil {
		return err.Error()
	}

	// Use AssignPropertiesFrom() to convert back to our original type
	var actual Connection_Properties_Spec
	err = actual.AssignProperties_From_Connection_Properties_Spec(&other)
	if err != nil {
		return err.Error()
	}

	// Check for a match
	match := cmp.Equal(subject, actual, cmpopts.EquateEmpty())
	if !match {
		actualFmt := pretty.Sprint(actual)
		subjectFmt := pretty.Sprint(subject)
		result := diff.Diff(subjectFmt, actualFmt)
		return result
	}

	return ""
}

