// Generator of Connection_Properties_Spec instances for property testing - lazily instantiated by
// Connection_Properties_SpecGenerator()
var connection_Properties_SpecGenerator gopter.Gen

// Connection_Properties_SpecGenerator returns a generator of Connection_Properties_Spec instances for property testing.
// We first initialize connection_Properties_SpecGenerator with a simplified generator based on the
// fields with primitive types then replacing it with a more complex one that also handles complex fields
// to ensure any cycles in the object graph properly terminate.
func Connection_Properties_SpecGenerator() gopter.Gen {
	if connection_Properties_SpecGenerator != nil {
		return connection_Properties_SpecGenerator
	}

	generators := make(map[string]gopter.Gen)
	AddIndependentPropertyGeneratorsForConnection_Properties_Spec(generators)
	connection_Properties_SpecGenerator = gen.Struct(reflect.TypeOf(Connection_Properties_Spec{}), generators)

	// The above call to gen.Struct() captures the map, so create a new one
	generators = make(map[string]gopter.Gen)
	AddIndependentPropertyGeneratorsForConnection_Properties_Spec(generators)
	AddRelatedPropertyGeneratorsForConnection_Properties_Spec(generators)
	connection_Properties_SpecGenerator = gen.Struct(reflect.TypeOf(Connection_Properties_Spec{}), generators)

	return connection_Properties_SpecGenerator
}

